import{_ as n,o as e,c as r,l as o,t as s,N as a}from"./chunks/framework.CMqbtke2.js";const T=JSON.parse('{"title":"pr | x-cmd man (man1) | convert text files for printing","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | pr - convert text files for printing","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"pr | x-cmd man (man1) | convert text files for printing"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | pr - convert text files for printing"}]]},"headers":[],"params":{"isMan":true,"man":"pr","category":"man1","desc":"convert text files for printing"},"relativePath":"man1/pr.md","filePath":"man1/pr.md"}'),d={name:"man1/pr.md"},g={class:"visually-hidden"},i=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>pr - convert text files for printing</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>pr</strong> [<em>OPTION</em>]... [<em>FILE</em>]...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Paginate or columnate FILE(s) for printing.</p><p>With no FILE, or when FILE is -, read standard input.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt>+FIRST_PAGE[:LAST_PAGE], <strong>--pages</strong>=<em>FIRST_PAGE[</em>:LAST_PAGE]</dt><dd>begin [stop] printing with page FIRST_[LAST_]PAGE</dd><dt><strong>-COLUMN</strong>, <strong>--columns</strong>=<em>COLUMN</em></dt><dd>output COLUMN columns and print columns down, unless <strong>-a</strong> is used. Balance number of lines in the columns on each page</dd><dt><strong>-a</strong>, <strong>--across</strong></dt><dd>print columns across rather than down, used together with <strong>-COLUMN</strong></dd><dt><strong>-c</strong>, <strong>--show-control-chars</strong></dt><dd>use hat notation (^G) and octal backslash notation</dd><dt><strong>-d</strong>, <strong>--double-space</strong></dt><dd>double space the output</dd><dt><strong>-D</strong>, <strong>--date-format</strong>=<em>FORMAT</em></dt><dd>use FORMAT for the header date</dd><dt><strong>-e[CHAR[WIDTH]]</strong>, <strong>--expand-tabs</strong>[=<em>CHAR[WIDTH]</em>]</dt><dd>expand input CHARs (TABs) to tab WIDTH (8)</dd><dt><strong>-F</strong>, <strong>-f</strong>, <strong>--form-feed</strong></dt><dd>use form feeds instead of newlines to separate pages (by a 3-line page header with <strong>-F</strong> or a 5-line header and trailer without <strong>-F</strong>)</dd><dt><strong>-h</strong>, <strong>--header</strong>=<em>HEADER</em></dt><dd>use a centered HEADER instead of filename in page header, <strong>-h</strong> &quot;&quot; prints a blank line, don&#39;t use <strong>-h</strong>&quot;&quot;</dd><dt><strong>-i[CHAR[WIDTH]]</strong>, <strong>--output-tabs</strong>[=<em>CHAR[WIDTH]</em>]</dt><dd>replace spaces with CHARs (TABs) to tab WIDTH (8)</dd><dt><strong>-J</strong>, <strong>--join-lines</strong></dt><dd>merge full lines, turns off <strong>-W</strong> line truncation, no column alignment, <strong>--sep-string</strong>[=<em>STRING</em>] sets separators</dd><dt><strong>-l</strong>, <strong>--length</strong>=<em>PAGE_LENGTH</em></dt><dd>set the page length to PAGE_LENGTH (66) lines (default number of lines of text 56, and with <strong>-F</strong> 63). implies <strong>-t</strong> if PAGE_LENGTH &lt;= 10</dd><dt><strong>-m</strong>, <strong>--merge</strong></dt><dd>print all files in parallel, one in each column, truncate lines, but join lines of full length with <strong>-J</strong></dd><dt><strong>-n[SEP[DIGITS]]</strong>, <strong>--number-lines</strong>[=<em>SEP[DIGITS]</em>]</dt><dd>number lines, use DIGITS (5) digits, then SEP (TAB), default counting starts with 1st line of input file</dd><dt><strong>-N</strong>, <strong>--first-line-number</strong>=<em>NUMBER</em></dt><dd>start counting with NUMBER at 1st line of first page printed (see +FIRST_PAGE)</dd><dt><strong>-o</strong>, <strong>--indent</strong>=<em>MARGIN</em></dt><dd>offset each line with MARGIN (zero) spaces, do not affect <strong>-w</strong> or <strong>-W</strong>, MARGIN will be added to PAGE_WIDTH</dd><dt><strong>-r</strong>, <strong>--no-file-warnings</strong></dt><dd>omit warning when a file cannot be opened</dd><dt><strong>-s[CHAR]</strong>, <strong>--separator</strong>[=<em>CHAR</em>]</dt><dd>separate columns by a single character, default for CHAR is the &lt;TAB&gt; character without <strong>-w</strong> and &#39;no char&#39; with <strong>-w</strong>. <strong>-s[CHAR]</strong> turns off line truncation of all 3 column options (<strong>-COLUMN</strong>|-a <strong>-COLUMN</strong>|-m) except <strong>-w</strong> is set</dd><dt><strong>-S[STRING]</strong>, <strong>--sep-string</strong>[=<em>STRING</em>]</dt><dd>separate columns by STRING, without <strong>-S</strong>: Default separator &lt;TAB&gt; with <strong>-J</strong> and &lt;space&gt; otherwise (same as <strong>-S</strong>&quot; &quot;), no effect on column options</dd><dt><strong>-t</strong>, <strong>--omit-header</strong></dt><dd>omit page headers and trailers; implied if PAGE_LENGTH &lt;= 10</dd><dt><strong>-T</strong>, <strong>--omit-pagination</strong></dt><dd>omit page headers and trailers, eliminate any pagination by form feeds set in input files</dd><dt><strong>-v</strong>, <strong>--show-nonprinting</strong></dt><dd>use octal backslash notation</dd><dt><strong>-w</strong>, <strong>--width</strong>=<em>PAGE_WIDTH</em></dt><dd>set page width to PAGE_WIDTH (72) characters for multiple text-column output only, <strong>-s[char]</strong> turns off (72)</dd><dt><strong>-W</strong>, <strong>--page-width</strong>=<em>PAGE_WIDTH</em></dt><dd>set page width to PAGE_WIDTH (72) characters always, truncate lines, except <strong>-J</strong> option is set, no interference with <strong>-S</strong> or <strong>-s</strong></dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Pete TerMaat and Roland Huebner.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/pr%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/pr\\</a>&gt; <br> or available locally via: info &#39;(coreutils) pr invocation&#39;</p>',17);function l(t,p,h,m,c,u){return e(),r("div",null,[o("h1",g,s(t.$params.man),1),i])}const w=n(d,[["render",l]]);export{T as __pageData,w as default};
